// ── Default items (used as seed in the builder) ────────────────────────────

export const DEFAULT_PROGRAM_ITEMS: ProgramItem[] = [
  { id: "p1", time: "13:00", title: "Aankomst",  description: "Welkom bij onze trouwdag",  iconId: "welkom"  },
  { id: "p2", time: "14:00", title: "Ceremonie", description: "Het ja-woord moment",        iconId: "ringen"  },
  { id: "p3", time: "17:00", title: "Borrel",    description: "Toasten op het geluk",       iconId: "toost"   },
  { id: "p4", time: "19:00", title: "Diner",     description: "Geniet van het feestmaal",   iconId: "cutlery" },
  { id: "p5", time: "22:00", title: "Feest",     description: "Dansen tot in de nacht",     iconId: "feest"   },
]

// ── Component ──────────────────────────────────────────────────────────────

interface Props {
  items: ProgramItem[]
  sc: SC
  programLayout?: ProgramLayout
  builderMode?: boolean
  onImagePositionChange?: (id: string, x: number, y: number) => void
}

export default function EventProgramPreview({
  items, sc, programLayout = "centered", builderMode, onImagePositionChange,
}: Props) {
  const sorted = items.slice().sort((a, b) => a.time.localeCompare(b.time))
  const list = sorted
  const faded = 1

  return (
    <div className="@container" style={{ backgroundColor: sc.bodyBackground ? "transparent" : sc.navBg, fontFamily: sc.fontFamily }}>
      <div style={{ padding: "36px 32px 52px" }}>
        <h2 style={{ fontSize: "2.25rem", fontWeight: sc.fontPageTitlesWeight, color: sc.headingColor, fontFamily: sc.fontPageTitles, textAlign: "center", margin: "0 0 28px" }}>
          Programma
        </h2>

        {/* ── Centered — strict 3-column grid, text always middle ─────────── */}
        {programLayout === "centered" && (
          <div style={{ display: "flex", flexDirection: "column", gap: sc.goldBorder ? 12 : 0 }}>
            {list.map((item, i) => {
              const inner = (
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "110px 1fr",
                    alignItems: "center",
                    gap: 24,
                    padding: sc.goldBorder ? "24px 28px" : "28px 0",
                    borderBottom: !sc.goldBorder && i < list.length - 1 ? `1px dashed ${sc.accent}35` : "none",
                    opacity: faded,
                  }}
                >
                  <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
                    <span style={{ color: sc.accent }}>
                      <ProgramIcon iconId={item.iconId} size={80} strokeWidth={1.5} />
                    </span>
                    <span style={{ fontSize: "1.75rem", fontWeight: 700, color: sc.labelColor, letterSpacing: "0.02em", lineHeight: 1 }}>
                      {item.time}
                    </span>
                  </div>
                  <div>
                    {item.title && (
                      <p style={{ fontSize: "1.25rem", fontWeight: 800, color: sc.goldBorder ? (sc.cardText ?? sc.headingColor) : sc.headingColor, margin: "0 0 6px", lineHeight: 1.2 }}>
                        {item.title}
                      </p>
                    )}
                    {item.description && (
                      <p className="min-w-0 break-words" style={{ fontSize: "0.9375rem", fontWeight: 400, color: sc.goldBorder ? (sc.cardText ?? sc.bodyText) : sc.bodyText, margin: 0, lineHeight: 1.6 }}>
                        {item.description}
                      </p>
                    )}
                  </div>
                </div>
              )
              if (sc.goldBorder && sc.cardBg) {
                return (
                  <div key={item.id ?? i} style={{ backgroundColor: sc.cardBg, border: `2px solid ${sc.accent}`, borderRadius: 16, overflow: "hidden" }}>
                    {inner}
                  </div>
                )
              }
              return <div key={item.id ?? i}>{inner}</div>
            })}
          </div>
        )}

        {/* ── Timeline ──────────────────────────────────────────────────── */}
        {programLayout === "timeline" && (
          <div className="relative @md:pl-[148px]">
            {list.map((item, i) => {
              const isLast = i === list.length - 1
              return (
                <div
                  key={item.id ?? i}
                  className={`relative pl-[68px] @md:pl-0 ${isLast ? "pb-0" : "pb-4 @md:pb-3"}`}
                  style={{ opacity: faded }}
                >
                  {/* ── Connector line: mobile center = left-[34px] (6px+28px), desktop = @md:left-[-84px] ── */}
                  {!isLast && (
                    <div
                      className="absolute left-[34px] top-7 bottom-[-16px] @md:left-[-84px] @md:top-16 @md:bottom-[-12px] w-[3px] rounded-sm z-0"
                      style={{ backgroundColor: `${sc.accent}35` }}
                    />
                  )}
                  {/* ── Icon circle ── */}
                  <div
                    className="absolute left-[6px] top-0 w-14 h-14 @md:left-[-148px] @md:w-32 @md:h-32 rounded-full flex items-center justify-center z-[2]"
                    style={{ backgroundColor: sc.navBg, border: `4px solid ${sc.accent}55`, color: sc.accent }}
                  >
                    <ProgramIcon iconId={item.iconId} strokeWidth={1.5} className="w-8 h-8 @md:w-20 @md:h-20" />
                  </div>
                  {/* ── Content ── */}
                  <div className="relative z-[1] pt-1 min-w-0 @md:pt-4">
                    <h3
                      className="text-base font-extrabold leading-tight min-w-0 break-words @md:text-2xl mb-1 @md:mb-2"
                    >
                      <span style={{ color: sc.labelColor }} className="mr-2">{item.time}</span>
                      {item.title && <span style={{ color: sc.headingColor }}>{item.title}</span>}
                    </h3>
                    <p
                      className="text-sm font-normal leading-relaxed min-w-0 break-words @md:text-lg @md:min-h-[6rem]"
                      style={{ color: sc.bodyText }}
                    >
                      {item.description ?? ""}
                    </p>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}
